import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.CtWPcAmt.js";const m=JSON.parse('{"title":"第 6 章：横向比较与个人选型","description":"AI Agent 零基础教程","frontmatter":{"title":"第 6 章：横向比较与个人选型","description":"AI Agent 零基础教程","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"selection/README.md","filePath":"selection/README.md","lastUpdated":null}'),d={name:"selection/README.md"};function l(n,t,s,i,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="第-6-章-横向比较与个人选型" tabindex="-1">第 6 章：横向比较与个人选型 <a class="header-anchor" href="#第-6-章-横向比较与个人选型" aria-label="Permalink to &quot;第 6 章：横向比较与个人选型&quot;">​</a></h1><blockquote><p>状态：正文完成（2026-08-13）</p><p>数据来源：2026-08-12 七款产品统一基准实测；评分底稿 <code>docs/12-benchmark-scoring.md</code>；正式选择矩阵 <code>docs/10-selection-matrix.md</code>；产品页见 <a href="/selection/05-overview.html">第 5 章</a></p></blockquote><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>第 5 章给了你七份独立的体验报告，但你可能还是不知道「到底该装哪一款」。本章把同一基准任务下的实测结果汇总成<strong>一张可对照的选择表</strong>，给你一条<strong>按自己条件走的新手决策路径</strong>，并展示一份<strong>有理由的个人选型结论</strong>作为示范——最终帮你做出「先试用哪两款」的决定，而不是替你排名。</p><h2 id="本章三份产出" tabindex="-1">本章三份产出 <a class="header-anchor" href="#本章三份产出" aria-label="Permalink to &quot;本章三份产出&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th><th>适合谁</th></tr></thead><tbody><tr><td><a href="/selection/01-comparison-table.html">1. 横向选择表</a></td><td>六维评分总表 + 信息维度 + 关键差异点，说明为什么不排名</td><td>想直接看数据对照的人</td></tr><tr><td><a href="/selection/02-decision-path.html">2. 新手决策路径</a></td><td>按「硬约束 → 任务类型 → 偏好」四步走到 1–2 款候选</td><td>不确定从哪开始的人</td></tr><tr><td><a href="/selection/03-personal-conclusion.html">3. 个人选型结论</a></td><td>作者基于真实任务的选型示范 + 三类典型读者结论</td><td>想要一个完整样例的人</td></tr></tbody></table><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>先过滤「能不能用」，再比较「好不好用」</strong>：地区、账号、支付、资料合规是硬约束，能力再强也不值得为不可用的服务冒险（Claude 阻断案例就是反例）；</li><li><strong>不做总分排名</strong>：七款产品的效率与成本使用四种不同单位（Credits、积分、人民币、API 账单），且托管路径与 BYOK 路径本质不同，任何单一数字排名都会误导；</li><li><strong>按你的任务选</strong>：办公为主的零基础用户和代码为主的技术用户，最优起点完全不同；</li><li><strong>先免费试用 1–2 款</strong>，用你自己的真实任务复测一遍（本章末尾提供可复用流程），再决定是否付费。</li></ol><h2 id="与第-5-章的关系" tabindex="-1">与第 5 章的关系 <a class="header-anchor" href="#与第-5-章的关系" aria-label="Permalink to &quot;与第 5 章的关系&quot;">​</a></h2><p>本章不重复产品细节。每条结论引用第 5 章对应页面与 <code>docs/12</code> 证据卡；证据边界（TraeWork/QoderWork 变更未验证、代码优势任务待 benchmark v2、Claude 无性能数据）在本章选择表中一并标注，不隐藏。</p>',10)])])}const u=e(d,[["render",l]]);export{m as __pageData,u as default};
